// Define the DType enum representing all the given types.
// Each variant corresponds to one dtype with the kind implied.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DType {
    Bool,         // boolean 'b'
    Int8, Int16, Int32, Int64,          // signed int 'i'
    UInt8, UInt16, UInt32, UInt64,      // unsigned int 'u'
    Float32, Float64,                   // floating point 'f'
    Complex64, Complex128,              // complex 'c'
    Object                            // object 'O'
}

impl DType {
    // Returns the kind character as specified:
    // 'b' for boolean, 'i' for signed integer, 'u' for unsigned integer, 'f' for floating,
    // 'c' for complex, 'O' for object.
    fn kind(&self) -> char {
        use DType::*;
        match self {
            Bool => 'b',
            Int8 | Int16 | Int32 | Int64 => 'i',
            UInt8 | UInt16 | UInt32 | UInt64 => 'u',
            Float32 | Float64 => 'f',
            Complex64 | Complex128 => 'c',
            Object => 'O',
        }
    }

    // Returns the precedence value as specified.
    fn precedence(&self) -> u8 {
        use DType::*;
        match self {
            Bool => 0,
            Int8 => 1,
            Int16 => 2,
            Int32 => 3,
            Int64 => 4,
            UInt8 => 5,
            UInt16 => 6,
            UInt32 => 7,
            UInt64 => 8,
            Float32 => 9,
            Float64 => 10,
            Complex64 => 11,
            Complex128 => 12,
            Object => 13,
        }
    }
}

// Task 1: find_max_precedence_type: Given a non-empty collection of dtypes,
// return a dtype from the collection with the greatest precedence.
fn find_max_precedence_type(types: Vec<DType>) -> DType {
    assert!(!types.is_empty(), "Input collection must be non-empty");

    // Iterate over all types in the vector and find the one with max precedence.
    // Since the input is non-empty, we can safely unwrap.
    *types.iter().max_by_key(|dt| dt.precedence()).unwrap()
}

// Task 2: find_common_type: Given two collections, array_types and scalar_types,
// compute the common dtype as per the problem description.
// Return Option<DType>: None if both inputs empty, else Some with the common type.
fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    // Both empty -> None
    if array_types.is_empty() && scalar_types.is_empty() {
        return None;
    }

    // Only array types given
    if !array_types.is_empty() && scalar_types.is_empty() {
        return Some(find_max_precedence_type(array_types));
    }

    // Only scalar types given
    if array_types.is_empty() && !scalar_types.is_empty() {
        return Some(find_max_precedence_type(scalar_types));
    }

    // Both non-empty: find max in each, compare kinds, decide accordingly
    let max_array = find_max_precedence_type(array_types);
    let max_scalar = find_max_precedence_type(scalar_types);

    if max_array.kind() == max_scalar.kind() {
        // same kind: return max from array collection
        Some(max_array)
    } else {
        // different kinds: return max from scalar collection
        Some(max_scalar)
    }
}

